#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Geospatial : 1

META "description" "Synthetic REA oracle world: GeoViewpoint navType and headlight attributes in a 3.2 XML scene (aliases of its private NavigationInfo). Authored."

DEF ORIGIN GeoOrigin {
  geoCoords 47.6 -122.3 0
  rotateYUp TRUE
}

DEF GV GeoViewpoint {
  geoOrigin USE ORIGIN
  description "xml"
  position 47.598 -122.3 200
  orientation 1 0 0 1.2
  navigationInfo NavigationInfo {
    type [
      "WALK",
      "ANY"
    ]
    headlight FALSE
  }
}

GeoLocation {
  geoOrigin USE ORIGIN
  geoCoords 47.6 -122.3 0
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.8 0.5 0.2
      }
    }
    geometry Box {
      size 60 60 60
    }
  }
}

